    Differential Revision: https://phabricator.services.mozilla.com/D280822

diff --git a/mail/app/profile/all-thunderbird.js b/mail/app/profile/all-thunderbird.js
index 1d7f49e9e6e..137c091d5c4 100644
--- a/mail/app/profile/all-thunderbird.js
+++ b/mail/app/profile/all-thunderbird.js
@@ -1491,6 +1491,12 @@ pref("mail.inappnotifications.bypass-filtering", false);
 // TODO: Remove this when PKCE is fully rolled out for Yahoo/AOL/AT&T
 pref("mail.inappnotifications.pkceUpgradeForYahooAol", false);

+// Whether Thunderbird is running under Flatpak or Snap.
+// These are set at startup each run so they reflect the current runtime.
+// Used to notify about upcoming changes via in-app notification.
+pref("mail.inappnotifications.isFlatpak", false);
+pref("mail.inappnotifications.isSnap", false);
+
 #ifdef NIGHTLY_BUILD
 // Enable the new experimental conversation view based on Gloda.
 pref("mail.thread.conversation.enabled", false);
diff --git a/mail/components/MailGlue.sys.mjs b/mail/components/MailGlue.sys.mjs
index c3dee3d6b43..025c302c635 100644
--- a/mail/components/MailGlue.sys.mjs
+++ b/mail/components/MailGlue.sys.mjs
@@ -588,11 +588,47 @@ MailGlue.prototype = {
     }
   },

+  /**
+   * Set prefs if we appear to be running under Flatpak or Snap.
+   *
+   * Uses env vars first (easy to test by simulating env vars),
+   * then falls back to distribution.id (packager-provided).
+   *
+   * These prefs are set on every startup so profiles can be reused
+   * across different installations.
+   */
+  _setFlatpakOrSnapPref() {
+    if (AppConstants.platform != "linux") {
+      Services.prefs.setBoolPref("mail.inappnotifications.isFlatpak", false);
+      Services.prefs.setBoolPref("mail.inappnotifications.isSnap", false);
+      return;
+    }
+
+    let isFlatpak = Services.env.exists("FLATPAK_ID");
+    let isSnap =
+      Services.env.exists("SNAP") || Services.env.exists("SNAP_NAME");
+
+    if (!isFlatpak && !isSnap) {
+      const distId = Services.prefs
+        .getDefaultBranch("")
+        .getCharPref("distribution.id", "")
+        .toLowerCase();
+
+      isFlatpak = distId.includes("flatpak");
+      isSnap = distId.includes("snap");
+    }
+
+    Services.prefs.setBoolPref("mail.inappnotifications.isFlatpak", isFlatpak);
+    Services.prefs.setBoolPref("mail.inappnotifications.isSnap", isSnap);
+  },
+
   // Runs on startup, before the first command line handler is invoked
   // (i.e. before the first window is opened).
   _beforeUIStartup() {
     lazy.TBDistCustomizer.applyPrefDefaults();

+    this._setFlatpakOrSnapPref();
+
     const UI_VERSION_PREF = "mail.ui-rdf.version";
     this._isNewProfile = !Services.prefs.prefHasUserValue(UI_VERSION_PREF);

@@ -1340,6 +1376,8 @@ function reportPreferences() {
     "mail.delete_matches_sort_order",
     "mail.display_glyph",
     "mail.inappnotifications.pkceUpgradeForYahooAol",
